// Removes all residents generated by scripts/generate-load-test-data.js
// (every one is named starting with "LOADTEST "), plus any vehicles left
// on flats that end up with zero remaining residents. Also removes the
// audit_log entries these residents created, mirroring the pattern in
// scripts/cleanup-test-data.js.
//
// Run:  node scripts/cleanup-load-test-data.js
require('dotenv').config();
const { createClient } = require('@supabase/supabase-js');

const NAME_PREFIX = 'LOADTEST';

async function main() {
  const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  const { data: testResidents, error: fetchError } = await supabase
    .from('residents')
    .select('id, flat_number')
    .like('resident_name', `${NAME_PREFIX}%`);

  if (fetchError) {
    console.error('Failed to fetch load-test residents:', fetchError.message);
    process.exit(1);
  }

  console.log(`Found ${testResidents.length} load-test residents to remove.`);
  if (testResidents.length === 0) {
    console.log('Nothing to clean up.');
    return;
  }

  const ids = testResidents.map((r) => r.id);
  const flatNumbers = [...new Set(testResidents.map((r) => r.flat_number))];

  // Remove audit_log entries referencing these residents.
  const { error: auditError } = await supabase.from('audit_log').delete().in('target_id', ids);
  if (auditError) console.warn('Warning: failed to clean up audit_log entries:', auditError.message);

  // Delete the residents themselves (in batches, to avoid an overly long IN clause).
  const DELETE_BATCH = 200;
  let deleted = 0;
  for (let i = 0; i < ids.length; i += DELETE_BATCH) {
    const batch = ids.slice(i, i + DELETE_BATCH);
    const { error } = await supabase.from('residents').delete().in('id', batch);
    if (error) {
      console.error(`Failed to delete batch starting at ${i}:`, error.message);
    } else {
      deleted += batch.length;
      console.log(`  Deleted ${deleted}/${ids.length} residents`);
    }
  }

  // Any vehicles left on flats that now have zero residents are orphaned
  // test data too — remove vehicles on any flat_number that no longer has
  // an active resident.
  const { data: remainingResidents } = await supabase
    .from('residents')
    .select('flat_number')
    .in('flat_number', flatNumbers);
  const stillOccupied = new Set((remainingResidents || []).map((r) => r.flat_number));
  const orphanedFlats = flatNumbers.filter((f) => !stillOccupied.has(f));

  if (orphanedFlats.length > 0) {
    const { error: vehicleError, count } = await supabase
      .from('vehicles')
      .delete({ count: 'exact' })
      .in('flat_number', orphanedFlats);
    if (vehicleError) {
      console.warn('Warning: failed to clean up orphaned vehicles:', vehicleError.message);
    } else {
      console.log(`Removed ${count || 0} vehicles on flats with no remaining residents.`);
    }
  }

  console.log(`\nDone. Removed ${deleted} load-test residents.`);
}

main().catch((err) => {
  console.error('Cleanup failed:', err);
  process.exit(1);
});
